const e={title:"AI Readiness & Workforce Transition Index",subtitle:"Business Adaptation, Workforce Transformation and Operational AI Integration Across Emerging Enterprises",author:"Priyanshu Gupta"},t=60,a=[{dimension:"Strategic Intent",score:72,weight:"25%",subIndicators:"AI vision, leadership alignment, budget commitment",explanation:"The degree to which AI is embedded in organisational vision, leadership articulation, and resource allocation.",diagnostic:"Strong intent without operational capability is a common failure mode, but operational capability without strategic anchoring rarely scales beyond individual business units.",color:"#1D6AE5"},{dimension:"Digital Operations",score:61,weight:"25%",subIndicators:"Cloud adoption, workflow digitisation, API maturity",explanation:"The maturity of the digital infrastructure on which AI systems operate: cloud adoption, workflow digitisation, integration capability, and structured processes.",diagnostic:"Digital maturity determines whether AI remains a tool-level experiment or becomes embedded in repeatable operating workflows.",color:"#00A86B"},{dimension:"Data Readiness",score:54,weight:"25%",subIndicators:"Governance frameworks, pipeline quality, data stewardship",explanation:"The most technically determinative dimension: data governance, quality standards, pipeline architecture, and organisational data culture.",diagnostic:"AI systems are only as effective as the data they learn from and operate on. Data readiness is the binding constraint in this score profile.",color:"#F59E0B"},{dimension:"Workforce Adaptability",score:67,weight:"25%",subIndicators:"Reskilling pace, AI literacy, psychological readiness",explanation:"The human capital capacity to absorb and leverage AI tools, including reskilling investment, managerial AI literacy, and psychological safety.",diagnostic:"AI adoption becomes durable only when workers can experiment, evaluate outputs, and adapt roles without unmanaged career anxiety.",color:"#0A2540"}],i={paragraphs:["Across every major economy, artificial intelligence is no longer positioned at the periphery of business planning — it has moved decisively into the operational core. Yet the gap between organisations that articulate an AI ambition and those that successfully operationalise one has widened rather than narrowed since 2022.","The AI Readiness and Workforce Transition Index is an independent analytical framework constructed to examine how emerging enterprises are managing the concurrent pressures of operational AI integration and workforce adaptation.","The framework organises organisational AI readiness across four diagnostic dimensions — Strategic Intent, Digital Operations, Data Readiness, and Workforce Adaptability — each weighted equally to produce a Composite Index."],findings:["Strategic intent consistently outpaces data infrastructure readiness, the dimension that most directly determines whether pilots can be scaled.","Middle management AI literacy is the most underinvested and consequential lever in enterprise AI adoption.","SMEs face a structurally distinct adoption challenge shaped by capital constraints, vendor dependency, and limited internal technical capacity."]},n=[{stage:"1 · Awareness",description:"Leadership understands AI at a conceptual level; sporadic tool trials occur without structure.",barrier:"No roadmap or resource allocation",signal:"AI referenced in organisational strategy"},{stage:"2 · Exploration",description:"Cross-functional pilots launched; technology vendors assessed; early governance conversations begin.",barrier:"Skills gaps and fragmented data systems",signal:"Active pilot with defined success metrics"},{stage:"3 · Integration",description:"AI embedded in two or more core workflows; structured reskilling underway.",barrier:"Workflow redesign complexity; change fatigue",signal:"Measurable efficiency gains documented"},{stage:"4 · Optimisation",description:"Iterative model improvement cycles in place; AI informs strategic decisions.",barrier:"Ethics and governance structures lag deployment",signal:"Dedicated AI oversight function established"},{stage:"5 · Transformation",description:"AI woven into organisational identity; talent hired and evaluated on AI fluency.",barrier:"Sustaining innovation culture at scale",signal:"Board-level AI ROI reporting in place"}],r=[{title:"Skills Velocity Gap",text:"AI capability development outpaces conventional reskilling programme cycles by 6–12 months."},{title:"Managerial AI Fluency",text:"Middle management conceptual gaps create adoption bottlenecks that senior strategy cannot bypass."},{title:"Displacement Anxiety",text:"Worker concern frequently outpaces actual risk, requiring active and specific communication strategies."},{title:"Cultural Inertia",text:"Established workflows resist AI-assisted alternatives even when productivity gains are demonstrable."},{title:"Internal Equity Gaps",text:"Reskilling programme benefits tend to accrue disproportionately to already digitally capable workers."}],o=[{model:"Replacement-focused adaptation",summary:"Appropriate for genuinely automatable tasks, but applied too broadly when augmentation is the more realistic outcome.",useCase:"Use when the task is structurally automatable and transition support is required for affected roles."},{model:"Augmentation-focused adaptation",summary:"Frames AI as a multiplier of human productive capacity through judgment, problem framing, output evaluation, and stakeholder communication.",useCase:"Use for knowledge-work and operational roles where AI improves speed and quality without removing human accountability."},{model:"Transformation-focused adaptation",summary:"Redesigns roles and workflows from first principles around what AI can now handle and where human work should move.",useCase:"Use when the organisation has change capacity and can involve frontline workers in workflow redesign."}],s=[{recommendation:"Integrate AI literacy into management and enterprise training curricula",stakeholder:"Education & Accreditation Bodies",timeframe:"Near-term (1–2 yrs)",priority:"High"},{recommendation:"Create SME-targeted AI adoption grant framework",stakeholder:"Government / MSME Ministry",timeframe:"Near-term (1–2 yrs)",priority:"High"},{recommendation:"Develop national AI readiness benchmarking standard",stakeholder:"Policy & Research Institutes",timeframe:"Mid-term (2–3 yrs)",priority:"Medium"},{recommendation:"Build industry-university AI transition partnerships",stakeholder:"Enterprises + Academia",timeframe:"Mid-term (2–3 yrs)",priority:"High"},{recommendation:"Establish portable digital-skills certification system",stakeholder:"Professional Bodies",timeframe:"Long-term (3–5 yrs)",priority:"Medium"},{recommendation:"Fund longitudinal workforce transition research programme",stakeholder:"Research Councils",timeframe:"Long-term (3–5 yrs)",priority:"Medium"}],c={nature:"This is an independent analytical research project, not an empirical study with primary data collection. The analysis synthesises published institutional research to construct a conceptual framework that has not been validated through field surveys, expert panels, or psychometric testing.",limitations:["Not a peer-reviewed academic paper subject to external review","Independent analytical initiative","Not based on original field research, surveys, or structured interviews","Does not constitute a recommendation for any specific commercial AI product","Not a validated benchmarking instrument for organisational AI assessment"]};export{e as a,a as b,i as c,n as d,r as e,o as f,s as g,c as h,t as w};
